sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {
    var updates = [{
            table: 'x_hccc_hoc_ohs_ohs_assessment_info',
            field: 'ohs_assessment_additional_information',
            service: '5e6c61c71bf8c610813f844fdd4bcbbc' // OHS Assessment
        }


    ];

    for (var i = 0; i < updates.length; i++) {
        if (current.hr_service.toString() === updates[i].service.toString()) {
            var gr = new GlideRecord(updates[i].table.toString());

            gr.setValue('parent_case', current.sys_id);
            gr.insert();
            current.setValue(updates[i].field.toString(), gr.sys_id.toString());
        }
    }


})(current, previous);
